// TestErrScript checks the sentinel error ErrScript. A caller matches it
// with errors.Is and reads its message, so it has a message and an
// identity of its own.
func TestErrScript(t *testing.T) {
	t.Parallel()

	others := []struct {
		name string
		err  error
	}{
		{"ErrTransfer", handoff.ErrTransfer},
		{"ErrUnknownSide", handoff.ErrUnknownSide},
		{"ErrUnknownEvent", handoff.ErrUnknownEvent},
		{"ErrUnknownAction", handoff.ErrUnknownAction},
	}

	t.Run("Error", func(t *testing.T) {
		t.Parallel()

		t.Run("returns a message", func(t *testing.T) {
			t.Parallel()
			assert.NotNil(t, handoff.ErrScript, "ErrScript is assigned")
			assert.NotEqual(t, handoff.ErrScript.Error(), "", "ErrScript has a message")
		})

		t.Run("opens the message with the package prefix", func(t *testing.T) {
			t.Parallel()
			assert.HasPrefix(
				t,
				handoff.ErrScript.Error(),
				"handoff: ",
				"the message of ErrScript opens with the package prefix",
			)
		})

		t.Run("returns a message of its own", func(t *testing.T) {
			t.Parallel()
			for _, other := range others {
				expect.NotEqual(
					t,
					handoff.ErrScript.Error(),
					other.err.Error(),
					"ErrScript has the message of "+other.name,
				)
			}
		})

		t.Run("opens with the message of no other sentinel", func(t *testing.T) {
			t.Parallel()
			for _, other := range others {
				expect.False(t, strings.HasPrefix(handoff.ErrScript.Error(), other.err.Error()),
					"the message of ErrScript opens with the message of "+other.name)
			}
		})
	})

	t.Run("errors.Is", func(t *testing.T) {
		t.Parallel()

		t.Run("matches no other sentinel of the package", func(t *testing.T) {
			t.Parallel()
			for _, other := range others {
				expect.ErrorIsNot(t, handoff.ErrScript, other.err, "ErrScript does not match "+other.name)
			}
		})
	})
}

